    if (!fs.existsSync(PRISMA_DIR)) {
      fs.mkdirSync(PRISMA_DIR, { recursive: true });
    }
    fs.writeFileSync(STORE_PATH, JSON.stringify(inMemoryStore, null, 2), 'utf-8');
  } catch (err) {
    console.warn('[DB Store] Error saving store:', err);
  }
}

